export const CAP_R = 0.38;

// ------------------------------------------------------------------ the broken water main
export const PIPE: {a: {x: number; y: number; z: number}; b: {x: number; y: number; z: number}}[] = [
  {a: {x: 52, y: -1.0, z: -9}, b: {x: 67, y: -1.8, z: 6}}, {a: {x: 69, y: -1.5, z: 8.5}, b: {x: 76, y: -0.7, z: 16}},
];
export const PIPE_HALF = 0.45;
/** nearest point of the pipe's axis to a ground point: horizontal distance, the beam's top / bottom above the ground
 *  there, the axis point, and u along its length (0 = a end, 1 = b end) */
export const pipeAt = (p: XZ): {d: number; top: number; bottom: number; q: {x: number; y: number; z: number}; u: number; seg: number} => {
  let best = {d: 1e9, top: 0, bottom: 0, q: PIPE[0].a, u: 0, seg: 0};
  PIPE.forEach((s, i) => {
    const dx = s.b.x - s.a.x, dz = s.b.z - s.a.z, L2 = dx * dx + dz * dz;
    const u = clamp(((p.x - s.a.x) * dx + (p.z - s.a.z) * dz) / L2);
    const q = {x: s.a.x + dx * u, y: s.a.y + (s.b.y - s.a.y) * u, z: s.a.z + dz * u};
    const d = Math.hypot(p.x - q.x, p.z - q.z);
    if (d < best.d) { const g = groundH(q.x, q.z); best = {d, top: q.y + PIPE_HALF - g, bottom: q.y - PIPE_HALF - g, q, u, seg: i}; }
  });
  return best;
};
/** the north-east side of the first length's line (where heavy 1 came, and its wreck lies) */
export const neOfPipe = (p: XZ) => p.z - p.x + 61 < 0;
/** the gap between the water main's two lengths: the only way through it from the north-east to the south-west */
export const GATE: XZ = {x: 68.0, z: 7.25};

// ------------------------------------------------------------------ distances
// (D4's list predates the set's R3 change that removed the rim plates 7–9 where the Crew fight: skip those)
const POLYS = [...CRATER_SOLIDS, ...D4_SOLIDS.filter((s) => s.p[0] > 30 && s.p[0] < 46 && !/^cplate_[789]$/.test(s.key))].map((s) => {
  const v: XZ[] = [];
  for (let i = 0; i < s.p.length; i += 2) v.push({x: s.p[i], z: s.p[i + 1]});
  const cx = v.reduce((a, q) => a + q.x, 0) / v.length, cz = v.reduce((a, q) => a + q.z, 0) / v.length;
  const r = Math.max(...v.map((q) => Math.hypot(q.x - cx, q.z - cz)));
  return {key: s.key, h: s.h, v, c: {x: cx, z: cz}, r};
});
const segD = (p: XZ, a: XZ, b: XZ) => {
  const dx = b.x - a.x, dz = b.z - a.z, L = dx * dx + dz * dz;
  const t = L > 0 ? clamp(((p.x - a.x) * dx + (p.z - a.z) * dz) / L) : 0;
  return Math.hypot(p.x - a.x - dx * t, p.z - a.z - dz * t);
};
const inside = (p: XZ, H: XZ[]) => { let c = false; for (let i = 0, j = H.length - 1; i < H.length; j = i++) if ((H[i].z > p.z) !== (H[j].z > p.z) && p.x < ((H[j].x - H[i].x) * (p.z - H[i].z)) / (H[j].z - H[i].z) + H[i].x) c = !c; return c; };
const polyDist = (p: XZ, H: XZ[]) => { let d = 1e9; for (let i = 0; i < H.length; i++) d = Math.min(d, segD(p, H[i], H[(i + 1) % H.length])); return inside(p, H) ? -d : d; };
/** clearance (m) from a ground point to the nearest solid (pieces lower than stepH are stepped over), and which */
export const clearAt = (p: XZ, o: {stepH?: number; pipe?: boolean; wrecks?: boolean} = {}): {d: number; what: string} => {
  const stepH = o.stepH ?? 0.12;
  let best = {d: 1e9, what: ''};
  for (const P of POLYS) {
    if (P.h < stepH || Math.hypot(p.x - P.c.x, p.z - P.c.z) > P.r + 4) continue;
    const d = polyDist(p, P.v);
    if (d < best.d) best = {d, what: P.key};
  }
  if (o.pipe !== false) {
    const q = pipeAt(p);
    // past an end of a length the beam is not there (the box ends at its axis end)
    const s = PIPE[q.seg], ends = (q.u <= 0 || q.u >= 1);
    const d = ends ? Math.hypot(p.x - q.q.x, p.z - q.q.z) - PIPE_HALF * 0.5 : q.d - PIPE_HALF;
    if (d < best.d && q.top > stepH) best = {d, what: 'waterMain'};
    void s;
  }
  if (o.wrecks !== false) for (const w of UNIT_WRECK_CAPS) {
    let d = 1e9;
    for (let i = 1; i < w.pts.length; i++) d = Math.min(d, segD(p, w.pts[i - 1], w.pts[i]));
    d -= CAP_R;
    if (d < best.d) best = {d, what: w.key};
  }
  return best;
};
/** along a polyline: the smallest clearance and where */
export const pathClear = (pts: XZ[], o: Parameters<typeof clearAt>[1] = {}, step = 0.1): {d: number; what: string; at: XZ} => {
  let best = {d: 1e9, what: '', at: pts[0]};
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i], n = Math.max(1, Math.ceil(Math.hypot(b.x - a.x, b.z - a.z) / step));
    for (let k = 0; k <= n; k++) { const q = {x: lerp(a.x, b.x, k / n), z: lerp(a.z, b.z, k / n)}; const c = clearAt(q, o); if (c.d < best.d) best = {...c, at: q}; }
  }
  return best;
};
